selected.compute:
options = read('/input/options')
result = []
for k in range(goal['min_count'], goal['max_count'] + 1):
    for group in combinations(options, k):
        ids = [item['id'] for item in group]
        if valid(ids):
            result = ids
            break
    if result:
        break

selected.effects:
if exists('/output/selection'):
    current = read('/output/selection')
    if not valid(current):
        status('report')
else:
    write('/output/selection', result)
if receipt('report') == 'success':
    pass
elif receipt('report') == 'unknown':
    status('report')
elif receipt('report') == 'failure' or receipt('report') == 'unattempted':
    if not exists('/output/selection'):
        pass
    else:
        send('report', 'team', read('/output/selection'))
if exists('/tmp/cache'):
    delete('/tmp/cache')
